import "./About.css";

function About() {
  return (
    <div className="about-container">
      <h1> About MyFood </h1>{" "}
      <p>
        Welcome to MyFood— your one - stop destination for mouth - watering
        meals delivered hot and fresh.🍕🍔🍝{" "}
      </p>{" "}
      <p>
        We are passionate about food and committed to quality.From classic
        pizzas to creamy pastas, every bite is made with love and freshness.{" "}
      </p>{" "}
      <p>
        Our goal is to make food ordering simple, enjoyable, and satisfying.❤️{" "}
      </p>{" "}
    </div>
  );
}

export default About;
